entries.commands:
! ===== 创建 VLAN 并划入端口（ZXR10）=====
enable
configure terminal
vlan {{vlan_id}}
 name {{vlan_name}}
 exit
interface {{port}}
 switchport mode access
 switchport access vlan {{vlan_id}}
 no shutdown
 exit
exit
write
show vlan {{vlan_id}}

! ===== 静态路由（ZXR10）=====
enable
configure terminal
ip route {{dest_net}} {{mask}} {{next_hop}}
ip route 0.0.0.0 0.0.0.0 {{next_hop}}
! 浮动备份：最后一位是优先级/距离，越大越不优先
ip route {{dest_net}} {{mask}} {{backup_hop}} {{distance}}
exit
write
show ip route
show ip route {{dest_net}}

! ===== OSPF 基本配置（ZXR10）=====
enable
configure terminal
router ospf {{process_id}}
 router-id {{router_id}}
 network {{network}} {{wildcard}} area {{area_id}}
 passive-interface {{passive_port}}
 exit
exit
write
show ip ospf neighbor
show ip ospf route

! ===== ACL 配置与下发（ZXR10）=====
enable
configure terminal
acl extend number {{acl_number}}
 rule 1 permit ip {{src_net}} {{src_wild}} {{dst_net}} {{dst_wild}}
 rule 100 deny ip any any
 exit
interface {{port}}
 ip access-group {{acl_number}} in
 exit
exit
write
show acl {{acl_number}}

! ===== NAT / PAT 配置（ZXR10）=====
enable
configure terminal
interface {{inside_port}}
 ip address {{inside_ip}} {{inside_mask}}
 ip nat inside
 exit
interface {{outside_port}}
 ip address {{outside_ip}} {{outside_mask}}
 ip nat outside
 exit
acl standard number {{acl_number}}
 rule 1 permit {{src_net}} {{src_wild}}
 exit
ip nat inside source list {{acl_number}} interface {{outside_port}} overload
! 静态一对一映射（外网访问内网服务器）
ip nat inside source static {{inside_server}} {{public_ip}}
exit
write
show ip nat translations
